"use client";
import {ArtemisScope} from "./artemis-scope";
import type { ArtemisHeroContent } from "./components/hero-sections/content";
import View5 from "./components/hero-sections/variants/06-ai-marketplace";
const views={"ai-marketplace":View5};
export type { ArtemisHeroContent, ArtemisHeroCta, ArtemisHeroForm, ArtemisHeroImage, ArtemisHeroLink, ArtemisHeroLogo, ArtemisHeroNav, ArtemisHeroPrompt } from "./components/hero-sections/content";
export interface ArtemisHeroSectionsProps {className?:string;variant?:"ai-marketplace"; /** The words on the hero; anything left out keeps the layout's own copy. */ content?: Partial<ArtemisHeroContent>;}
export function ArtemisHeroSections({className,variant="ai-marketplace",content}:ArtemisHeroSectionsProps){const View=views[variant];return <ArtemisScope className={`art:[&>*]:mx-auto ${className??""}`}><View content={content}/></ArtemisScope>;}

// @zeus-internal

/** The words on a link, and where it goes. */
export interface ArtemisHeroLink {
  label: string;
  href: string;
}

/** The words on a button, and where it links. */
export interface ArtemisHeroCta {
  label: string;
  /** Where it links. analytics-flow and ai-teammates use only the label: their buttons scroll to the demo and open its brief. */
  href?: string;
}

/** An image, and the words that stand in for it (empty when it only decorates). */
export interface ArtemisHeroImage {
  src: string;
  alt: string;
}

/** A customer or partner, shown by name. */
export interface ArtemisHeroLogo {
  name: string;
}

/** The bar across the top of the layouts that have their own. */
export interface ArtemisHeroNav {
  /** The name beside the logo mark, and where it links. Every layout with a bar. */
  brand: ArtemisHeroLink;
  /** Links in the bar and its mobile menu. Every layout with a bar. */
  links: ArtemisHeroLink[];
  /** The sign-in link. decision-spectrum, ai-marketplace and signal-aurora; left out, they show none. */
  login?: ArtemisHeroLink;
  /** The button at the end of the bar. voice-mobile, decision-spectrum, defi-routing and ai-marketplace; left out, they show none. */
  cta?: ArtemisHeroLink;
  /** The button in the open mobile menu, where its words differ from `cta`. voice-mobile, decision-spectrum, defi-routing and ai-marketplace; left out, the menu shows `cta`. */
  menuCta?: ArtemisHeroLink;
}

/** An email field and its button. */
export interface ArtemisHeroForm {
  /** The field's label, read by screen readers. */
  label: string;
  /** The hint in the empty field. */
  placeholder: string;
  /** The button's words. */
  submit: string;
}

/** A box where visitors describe what they need. */
export interface ArtemisHeroPrompt {
  /** The small title over the box. */
  title: string;
  /** The field's name, read by screen readers. */
  label: string;
  /** Example requests that take turns in the empty box. */
  examples: string[];
  /** The send button's name, read by screen readers. */
  submit: string;
  /** The line shown once a request is sent. */
  confirmation: string;
  /** Requests under the box; choosing one fills it in. */
  suggestions: string[];
}

/** The words on an Artemis hero. Every layout reads this shape, so you can switch layouts and keep them. */
export interface ArtemisHeroContent {
  /** The hero's own bar with the brand, links and buttons. voice-mobile, decision-spectrum, defi-routing, ai-marketplace and signal-aurora. */
  nav?: ArtemisHeroNav;
  /** A short line over the headline. All layouts but decision-spectrum. */
  badge?: string;
  /** Small faces beside the badge; screen readers skip them. split-demo. */
  avatars?: ArtemisHeroImage[];
  /** The headline, or its first part where a layout splits it. All layouts. */
  headline: string;
  /** The rest of the headline. analytics-flow mutes it and decision-spectrum sets it bolder; ai-teammates, voice-mobile, defi-routing and ai-marketplace start it on a new line; signal-aurora and split-demo run it on after the headline. It goes with `headline`: give a headline without it and the headline shows on its own; leave both out to keep the layout's own. */
  headlineAccent?: string;
  /** The paragraph under the headline. All layouts. */
  subhead: string;
  /** The main button. analytics-flow, ai-teammates, voice-mobile, decision-spectrum, signal-aurora and split-demo. */
  cta?: ArtemisHeroCta;
  /** The second button. analytics-flow, ai-teammates, voice-mobile, decision-spectrum and split-demo. */
  secondaryCta?: ArtemisHeroCta;
  /** An email field and its button, in place of buttons. defi-routing. */
  form?: ArtemisHeroForm;
  /** A box for describing what you need, in place of buttons. ai-marketplace. */
  prompt?: ArtemisHeroPrompt;
  /** A short line under the buttons. analytics-flow, ai-teammates and defi-routing. */
  note?: string;
  /** Short points with a check mark, under the buttons; two look best. voice-mobile. */
  points?: string[];
  /** A line under the picture beside the words. ai-teammates. */
  caption?: string;
  /** The line over the logos. decision-spectrum and split-demo. */
  logosTitle?: string;
  /** Customers or partners, shown by name. decision-spectrum, signal-aurora and split-demo. */
  logos?: ArtemisHeroLogo[];
}

